(function(){
'use strict';
const D=window.SAMPLE,M=window.DistilleryMath,S=window.StoryPanels,P=M.prepare(D),$=id=>document.getElementById(id);
const colors=['#edb85c','#9bcaba','#bca5e8','#e88a81'];
const labels={ridge:'Ridge',elastic:'Elastic Net',huber:'Huber',quantile:'Q95'};
let state={lang:'pl',scene:0,ownScale:false,guess:null,route:null,stage:0,lambda:.05,model:'ridge',metric:'p99',mb:100,bytesPerToken:4,context:1000000,decision:null,quiz:null,reduce:matchMedia('(prefers-reduced-motion: reduce)').matches};
let fit=M.ridge(P,state.lambda),animation=0,flowTimer=0,chartObserver=null;
const t=(pl,en)=>state.lang==='pl'?pl:en;
const n=(v,d=2)=>new Intl.NumberFormat(state.lang==='pl'?'pl-PL':'en-GB',{maximumFractionDigits:d}).format(v);
const count=(v,forms,en)=>n(v,0)+' '+(state.lang==='pl'?forms[new Intl.PluralRules('pl').select(v)]:en+(v===1?'':'s'));
const exact=v=>new Intl.NumberFormat(state.lang==='pl'?'pl-PL':'en-GB',{maximumFractionDigits:8}).format(v);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const by=s=>new TextEncoder().encode(s).length;
const packet=()=>M.evidence(D,P,fit);
const handoff=()=>M.handoff(D,P,fit);
const rawText=JSON.stringify({y:D.y,x:D.x}),rawBytes=by(rawText);
const stepNames=()=>[t('Hałas','Noise'),t('Kontekst','Context'),t('Destylacja','Distil'),t('Sygnał','Signal'),t('Jeszcze jedno','One more query')];
function intro(k,title,lead){return '<div class="intro"><p class="eyebrow">'+t('AKT ','ACT ')+(k+1)+' / 05 · '+t('POMIARY PRAWDZIWE. HISTORIA EDUKACYJNA.','REAL MEASUREMENTS. EDUCATIONAL STORY.')+'</p><h1>'+title+'</h1><p class="lead">'+lead+'</p></div>';}
function next(label){return '<div class="cta"><button class="text-button" data-back '+(state.scene===0?'disabled':'')+'>'+t('← Wróć','← Back')+'</button><button class="primary" data-next>'+label+' <span aria-hidden="true">→</span></button></div>';}
function notice(pl,en,kind=''){return '<div class="callout '+kind+'">'+t(pl,en)+'</div>';}
function warning(){return notice('<strong>Destylacja nie naprawia wejścia.</strong> W źródle 963 z 1 339 wpisów resmgr zastąpiono zerem. Nie znamy ich położenia. Ta niepewność dotyczy całego modelu, nie tylko słupka resmgr.','<strong>Distillation does not repair the input.</strong> 963 of 1,339 resmgr entries were zero-filled upstream. Their positions are unknown. The entire fit containing this feature inherits that uncertainty.','warning');}
function render(){
 if($('model-dialog').open)$('model-dialog').close();
 cancelAnimationFrame(animation);clearTimeout(flowTimer);if(chartObserver){chartObserver.disconnect();chartObserver=null;}
 document.documentElement.lang=state.lang;document.querySelector('.brand').href='#'+state.lang+'/0';document.body.dataset.scene=state.scene;document.body.classList.toggle('reduce-motion',state.reduce);
 $('language').textContent=state.lang==='pl'?'EN':'PL';$('language').setAttribute('aria-label',t('Switch to English','Przełącz na polski'));
 $('local-badge').textContent=t('Bez wysyłania danych','No data uploads');$('motion').textContent=t('Ogranicz ruch','Reduce motion');$('motion').setAttribute('aria-pressed',String(state.reduce));
 $('chapters').setAttribute('aria-label',t('Etapy historii','Story chapters'));
 $('chapters').innerHTML=stepNames().map((s,i)=>'<button type="button" data-scene="'+i+'" class="'+(i===state.scene?'active':'')+'" '+(i===state.scene?'aria-current="step"':'')+'><span class="nav-number">0'+(i+1)+'</span>'+s+'</button>').join('');
 $('footer-note').textContent=t('JAS-MIN × ONE MORE QUERY · EDYCJA 1 · PL / EN','JAS-MIN × ONE MORE QUERY · COURSE EDITION 1 · PL / EN');$('about').textContent=t('Dane, matematyka i granice ↗','Data, maths & limitations ↗');
 $('main').innerHTML=[noise,context,distil,signal,investigate][state.scene]();
 if(state.scene===0)$('main').querySelector('.intro').insertAdjacentHTML('afterend',S.onboarding(state.lang)+S.units(state.lang));
 if(state.scene===3)$('main').querySelector('.intro').insertAdjacentHTML('afterend','<div id="prediction-payoff"></div>');
 $('chapters').querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>navigate(+b.dataset.scene));
 $('main').querySelectorAll('[data-next]').forEach(b=>b.onclick=()=>navigate(Math.min(4,state.scene+1)));
 $('main').querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>navigate(Math.max(0,state.scene-1)));
 [bindNoise,bindContext,bindDistil,bindSignal,bindInvestigate][state.scene]();
}
function navigate(scene){state.scene=scene;history.replaceState(null,'','#'+state.lang+'/'+scene);render();$('main').focus({preventScroll:true});window.scrollTo({top:0,behavior:state.reduce?'instant':'smooth'});}
function noise(){
 const guess=state.guess===null?'':'<div class="callout">'+t('Obstawiasz: ','Your pick: ')+esc(D.features[state.guess])+t('. Zachowaj tę hipotezę. Sprawdzimy ją modelem — nie wysokością szczytu.','. Keep that hypothesis. We will examine it with a model, not the tallest peak.')+'</div>';
 return intro(0,t('Piwo stoi.<br><em>Produkcja leży.</em>','The beer is cold.<br><em>Production is frozen.</em>'),t('1 339 obserwacji. 6 695 liczb. Cztery wybrane zdarzenia. Wykresy pokazują, co zarejestrowano — ale sama wysokość szczytu nie mówi, od czego zacząć.','1,339 observations. 6,695 numbers. Four selected events. Charts show what was recorded, but the tallest peak alone cannot tell you where to start.'))+
 '<div class="layout"><section class="panel"><div class="panel-head"><p class="eyebrow">'+t('MONITORING / CAŁA ZACHOWANA SERIA','MONITORING / COMPLETE RETAINED SERIES')+'</p><div class="switches"><button id="shared" aria-pressed="'+!state.ownScale+'">'+t('Wspólna skala','Shared scale')+'</button><button id="separate" aria-pressed="'+state.ownScale+'">'+t('Rozdziel skale','Separate scales')+'</button></div></div><div class="data-strip" aria-hidden="true">'+D.x.slice(440,446).flatMap((r,i)=>[D.y[440+i],...r]).map(v=>'<span>'+n(v)+'</span>').join('')+'</div>'+D.features.map((name,j)=>'<div class="chart-row"><div class="chart-label"><span><i class="swatch" style="background:'+colors[j]+'"></i>'+esc(name)+'</span><b>'+t('szczyt ','peak ')+n(Math.max(...D.x.map(r=>r[j])),0)+' s</b></div><svg id="chart-'+j+'" role="img" aria-label="'+esc(name+'; '+t('sekundy oczekiwania w oknie','wait seconds per window'))+'"></svg></div>').join('')+'<div class="chart-row target-chart"><div class="chart-label"><span>'+t('CEL: DB Time / czas okna','TARGET: DB Time / window duration')+'</span><b>AAS (s/s)</b></div><svg id="chart-y" role="img" aria-label="DB Time / AAS"></svg></div><div class="chart-note"><span>'+t('oś X: numer obserwacji 1–1 339','X axis: observation index 1–1,339')+'</span><span>'+t('cztery wybrane cechy, nie cały AWR','four selected features, not a full AWR')+'</span></div></section><aside class="side-note"><div class="dialogue"><span class="speaker">DBA / 19:42</span>'+t('„Największy wykres. Mamy winnego. Zamawiam.”','“Biggest chart. Case closed. My round.”')+'</div><div class="dialogue"><span class="speaker">DEV / 19:42</span>'+t('„Duży to rozmiar kufla. Nie dowód.”','“Large is a beer size. Not evidence.”')+'</div><div><h3>'+t('Gdzie zajrzysz najpierw?','Where would you look first?')+'</h3>'+D.features.map((name,j)=>'<button class="choice '+(state.guess===j?'active':'')+'" data-guess="'+j+'" aria-pressed="'+(state.guess===j)+'">'+esc(name)+'</button>').join('')+'<div id="guess-feedback" class="feedback" aria-live="polite">'+guess+'</div></div><div id="scale-note">'+scaleNote()+'</div></aside></div>'+next(t('Może AI to ogarnie?','Maybe AI can handle it?'));
}
function scaleNote(){return state.ownScale?notice('<strong>O, pod spodem coś żyje.</strong> Własna skala ujawnia kształt — i może powiększyć szum. Nadal nie mówi, co jest ważne ani co powoduje problem.','<strong>There is life under that line.</strong> Individual scales reveal shape — and can magnify noise. They still do not establish importance or cause.'):notice('<strong>Wspólne 147 293 s na czterech osiach oczekiwań.</strong> Niskie serie wyglądają jak cisza. Kliknij „Rozdziel skale”: nie zmienimy ani jednej liczby.','<strong>The same 147,293 s on all four wait axes.</strong> Smaller series look silent. Click “Separate scales”: not a single measurement will change.');}
function drawCharts(morph=false){
 const common=Math.max(...D.x.flat()),start=performance.now(),duration=state.reduce||!morph?0:700;
 const settings=[0,1,2,3,'y'].map(j=>{const svg=$('chart-'+j),w=svg.clientWidth||600,h=j==='y'?76:79,v=j==='y'?D.y:D.x.map(r=>r[j]),max=Math.max(...v),goal=j==='y'||state.ownScale?max:common,prev=j==='y'?max:state.ownScale?common:max;svg.setAttribute('viewBox','0 0 '+w+' '+h);return {svg,w,h,v,goal,prev,j};});
 function frame(now){const p=duration?Math.min(1,(now-start)/duration):1,e=1-(1-p)**3;for(const c of settings){const {w,h,v,j,svg}=c,L=48,R=w-6,top=11,bottom=h-20,domain=c.prev+(c.goal-c.prev)*e;const path=v.map((y,i)=>(i?'L':'M')+(L+i/(v.length-1)*(R-L)).toFixed(2)+','+(bottom-y/domain*(bottom-top)).toFixed(2)).join('');svg.innerHTML='<title>'+esc(j==='y'?'DB Time / AAS':D.features[j])+'</title><line class="chart-grid" x1="'+L+'" y1="'+bottom+'" x2="'+R+'" y2="'+bottom+'"/><line class="chart-grid" x1="'+L+'" y1="'+top+'" x2="'+R+'" y2="'+top+'" stroke-dasharray="2 5"/><text class="chart-axis" x="0" y="'+(top+3)+'">'+n(domain>=1000?domain/1000:domain,domain>=1000?1:0)+(domain>=1000?'k':'')+'</text><text class="chart-axis" x="0" y="'+bottom+'">0</text><path class="chart-path" stroke="'+(j==='y'?'#f4f0e4':colors[j])+'" d="'+path+'"/><text class="chart-axis" x="'+L+'" y="'+(h-3)+'">1</text><text class="chart-axis" x="'+R+'" y="'+(h-3)+'" text-anchor="end">1 339</text>'; }if(p<1)animation=requestAnimationFrame(frame);}
 cancelAnimationFrame(animation);animation=requestAnimationFrame(frame);
}
function bindNoise(){drawCharts();chartObserver=new ResizeObserver(()=>drawCharts());chartObserver.observe($('chart-0'));for(const id of ['shared','separate'])$(id).onclick=()=>{state.ownScale=id==='separate';$('shared').setAttribute('aria-pressed',String(!state.ownScale));$('separate').setAttribute('aria-pressed',String(state.ownScale));$('scale-note').innerHTML=scaleNote();drawCharts(true);};document.querySelectorAll('[data-guess]').forEach(b=>b.onclick=()=>{state.guess=+b.dataset.guess;document.querySelectorAll('[data-guess]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});$('guess-feedback').innerHTML=notice(t('Obstawiasz: ','Your pick: ')+esc(D.features[state.guess])+t('. Zachowaj tę hipotezę. Wrócimy do niej w etapie „Sygnał”.','. Keep that hypothesis. We return to it in the Signal chapter.'),t('Obstawiasz: ','Your pick: ')+esc(D.features[state.guess])+t('. Zachowaj tę hipotezę. Wrócimy do niej w etapie „Sygnał”.','. Keep that hypothesis. We return to it in the Signal chapter.'));});}
function context(){return intro(1,t('Większy kontekst.<br><em>Nie większa pewność.</em>','More context.<br><em>Not more certainty.</em>'),t('AI potrzebuje dowodów, nie konkursu na najdłuższy załącznik. Najpierw wybierz, co zrobisz z raportami.','AI needs evidence, not an attachment-length contest. First, choose what to do with the reports.'))+
 '<div class="budget-grid"><section class="panel"><div class="document-pile" aria-hidden="true">'+[-2,-1,0,1,2].map((x)=>'<div class="paper" style="--x:'+(x*52)+'px;--r:'+(x*7)+'deg"><b>AWR / '+(x+3)+'</b><div class="paper-lines">DB Time · waits<br>SQL · latches · I/O<br>parse · mutex · CPU</div></div>').join('')+'</div><div class="panel-content"><h2>'+t('Wrzućmy wszystko?','Send the whole lot?')+'</h2><div class="field"><label for="volume">'+t('Rozmiar wyodrębnionego tekstu','Extracted text volume')+'<output id="volume-label"></output></label><input id="volume" type="range" min="1" max="1000" value="'+state.mb+'"></div><div class="budget-result"><strong id="token-estimate"></strong><span>'+t('szacowanych tokenów wejścia','estimated input tokens')+'</span></div><div id="budget-meter" class="meter"><div id="budget-fill" class="meter-fill"></div></div><p id="budget-description" class="subtle" aria-live="polite"></p><details><summary>'+t('Założenia, nie cennik ani specyfikacja modelu','Assumptions, not a price list or model specification')+'</summary><div class="inline-fields"><div class="field"><label for="bytes-token">'+t('Bajtów / token','Bytes / token')+'</label><input id="bytes-token" type="number" min="1" max="10" step=".5" value="'+state.bytesPerToken+'"></div><div class="field"><label for="context-limit">'+t('Nominalny budżet tokenów','Nominal token budget')+'</label><input id="context-limit" type="number" min="1000" max="10000000" step="1000" value="'+state.context+'"></div></div><p>'+t('tokeny ≈ MB × 1 000 000 / bajty na token. Na dane rezerwujemy 80% budżetu; 20% zostaje na instrukcje i odpowiedź. To ilustracja dla tekstu, nie pomiar tokenizacji AWR ani limit konkretnego modelu. Wiele paczek nie jest jednym wspólnym kontekstem.','tokens ≈ MB × 1,000,000 / bytes per token. Data gets 80% of the budget; 20% remains for instructions and the response. This illustrates text volume, not measured AWR tokenization or a specific model limit. Multiple chunks are not one shared context.')+'</p></details><p class="scenario-bridge">'+t('100 MB to scenariusz dużego zestawu raportów, nie rozmiar tej próbki. Tu celowo wybraliśmy tylko cztery zdarzenia i AAS: sama macierz liczb zajmuje około 25 kB. Tak mały wycinek można pokazać AI wprost. Modele dodają powtarzalny rachunek i precyzyjniejsze pytanie — nie magiczną kompresję.','100 MB is a large-report scenario, not the size of this sample. We deliberately selected just four events and AAS: the numerical matrix alone is about 25 kB. Such a small extract can go directly to AI. Models add reproducible calculations and a more precise question, not magical compression.')+'</p></div></section><aside class="side-note"><div class="dialogue"><span class="speaker">DEV</span>'+t('„A jak mu damy milion tokenów?”','“What if we give it a million tokens?”')+'</div><div class="dialogue"><span class="speaker">DBA</span>'+t('„To będzie miał milion tokenów. Nadal trzeba zadać dobre pytanie.”','“Then it will have a million tokens. We still need a good question.”')+'</div><h3>'+t('Wybierz wejście do analizy','Choose the starting point')+'</h3><button class="choice" id="raw-route">'+t('Najpierw cały tekst','All the text first')+'<small>'+t('Może być sensowne przy małym, dobrze dobranym materiale.','Can be reasonable for a small, well-chosen input.')+'</small></button><button class="choice" id="local-route">'+t('Najpierw lokalne modele','Local models first')+'<small>'+t('Podsumowanie + ograniczenia + odnośnik do źródeł.','Summary + limitations + access to source evidence.')+'</small></button><div id="route-feedback">'+routeNote()+'</div>'+notice('Nie wyceniamy fikcyjnego rachunku. Przy rozliczaniu tokenowym więcej wejścia to więcej płatnej pracy. Mniejszy pakiet nadal musi zawierać wystarczające dowody.','No invented bill. Under token-based pricing, more input means more billable work. A smaller packet must still contain sufficient evidence.')+'</aside></div>'+next(t('Uruchom lokalną destylarnię','Start the local distillery'));}
function routeNote(){if(!state.route)return '';return state.route==='raw'?notice('Da się. Ale dla dużego materiału trzeba zarządzać podziałem, selekcją i powrotami do źródeł. Pocięcie pliku nie tworzy automatycznie spójnej analizy.','Possible. But large inputs need chunking, selection and retrieval. Splitting a file does not automatically create a coherent analysis.'):notice('To nasza ścieżka: lokalnie policz relacje, zachowaj ograniczenia, a do LLM podaj pytanie i sprawdzalne punkty zaczepienia.','Our route: calculate relationships locally, retain limitations, then give the LLM a question and verifiable entry points.');}
function updateBudget(){const b=M.budget(state.mb,state.bytesPerToken,state.context);$('volume-label').textContent=n(state.mb,0)+' MB';$('token-estimate').textContent=n(b.tokens/1e6,2)+' M';$('budget-fill').style.width=Math.min(100,b.ratio*100)+'%';$('budget-meter').classList.toggle('over',b.ratio>1);$('budget-description').textContent=t('To ','That is ')+n(b.ratio,1)+t('× miejsca przeznaczonego na dane (','× the space reserved for data (')+n(b.available,0)+t(' tokenów). Dolna granica podziału: ',' tokens). Chunk-count lower bound: ')+count(b.lowerBoundChunks,{one:'paczka',few:'paczki',many:'paczek',other:'paczki'},'chunk')+t(', bez nakładania i narzutu.',', without overlap or overhead.');}
function bindContext(){updateBudget();function markRoute(){for(const [id,key] of [['raw-route','raw'],['local-route','local']])$(id).setAttribute('aria-pressed',String(state.route===key));}markRoute();$('volume').oninput=e=>{state.mb=+e.target.value;updateBudget();};for(const [id,key] of [['bytes-token','bytesPerToken'],['context-limit','context']])$(id).oninput=e=>{if(e.target.validity.valid&&+e.target.value>0){state[key]=+e.target.value;updateBudget();}};$('raw-route').onclick=()=>{state.route='raw';$('route-feedback').innerHTML=routeNote();markRoute();};$('local-route').onclick=()=>{state.route='local';$('route-feedback').innerHTML=routeNote();markRoute();};}
function apparatus(){return '<svg id="apparatus" class="distill-svg" viewBox="0 0 860 300" role="img" aria-label="'+t('Przepływ danych przez lokalne obliczenia, cztery modele i bramkę jakości','Data passing through local calculations, four models and the quality gate')+'"><title>'+t('Destylarnia dowodów','Evidence distillery')+'</title><path class="pipe" d="M158 135 H238 V78 H380 V137 H472 M472 137 H700 V195"/><path class="flow" d="M158 135 H238 V78 H380 V137 H472 H700 V195"/><rect x="24" y="79" width="139" height="132" rx="12" class="metal"/><path d="M25 124 H162 V199 Q162 211 150 211 H36 Q24 211 24 198Z" class="liquid"/><text x="93" y="115" text-anchor="middle" class="label">1 339 × 5</text><text x="93" y="152" text-anchor="middle">'+t('POMIARY','READINGS')+'</text><text x="93" y="174" text-anchor="middle">'+t('zostają lokalnie','stay local')+'</text><path class="copper" d="M270 173 Q260 114 295 91 L295 56 H329 V91 Q365 114 354 173 Q352 210 313 215 Q273 211 270 173Z"/><path class="metal" d="M285 216 H341 L352 235 H272Z"/><text x="312" y="133" text-anchor="middle" class="label">Δ → z</text><text x="312" y="155" text-anchor="middle">'+t('LOKALNIE','LOCALLY')+'</text><rect x="431" y="72" width="72" height="130" rx="10" class="metal"/><path d="M444 92 H490 L444 112 H490 L444 132 H490 L444 152 H490 L444 172 H490" stroke="#cd9959" stroke-width="3" fill="none"/><text x="466" y="230" text-anchor="middle">'+t('DOPASOWANIE','FITTING')+'</text>'+['Ridge','EN','Huber','Q95'].map((s,i)=>{const x=554+i*70;return '<path d="M'+x+' 155 V170 L'+(x-10)+' 184 V244 Q'+(x-10)+' 250 '+(x-4)+' 250 H'+(x+24)+' Q'+(x+30)+' 250 '+(x+30)+' 244 V184 L'+(x+20)+' 170 V155Z" class="bottle '+(i===3?'rejected':'')+'"/><rect x="'+(x-5)+'" y="210" width="30" height="31" rx="2" fill="'+(i===3?'#e88a8125':'#edb85c30')+'"/><text x="'+(x+10)+'" y="202" text-anchor="middle" class="'+(i===3?'danger-label':'label')+'">'+s+'</text><text x="'+(x+10)+'" y="277" text-anchor="middle" class="'+(i===3?'danger-label':'')+'">'+(i===3?'STOP':'✓')+'</text>';}).join('')+'<text x="25" y="275">'+t('CZTERY MODELE. RÓŻNE PYTANIA. ŻADNYCH WYROKÓW.','FOUR MODELS. DIFFERENT QUESTIONS. NO VERDICTS.')+'</text></svg>';}
function stages(){return [t('Jakość','Quality'),t('Różnice','Changes'),t('Skala','Scale'),t('Modele','Models'),t('Bramka','Gate'),t('Etykieta','Label')];}
function distil(){return intro(2,t('Nie wysyłaj beczki.<br><em>Najpierw destyluj sygnał.</em>','Don’t send the barrel.<br><em>Distil the signal first.</em>'),t('Liczby zostają na miejscu. Modele wyciągają użyteczne relacje. Na etykietę trafiają także wątpliwości — nie tylko mocne wnioski.','Keep the numbers local. Models extract useful relationships. Doubts go on the label too — not just confident-looking results.'))+
 '<div class="layout"><section class="panel"><div class="panel-head"><p class="eyebrow">'+t('JAS-MIN / LOKALNY PRZEPŁYW DANYCH','JAS-MIN / LOCAL DATA FLOW')+'</p><button id="play-flow">'+t('▶ Pokaż przepływ','▶ Show the flow')+'</button></div><p id="flow-status" class="flow-status" aria-live="polite"></p><div class="distillery">'+apparatus()+'<div class="stage-controls">'+stages().map((s,i)=>'<button data-stage="'+i+'" aria-pressed="'+(i===state.stage)+'"><span>0'+(i+1)+'</span>'+s+'</button>').join('')+'</div></div><div class="calc" id="calc-content" aria-live="polite">'+calcContent()+'</div></section><aside class="side-note"><div class="dialogue"><span class="speaker">DBA</span>'+t('„To nie magia. To matematyka z porządną etykietą.”','“Not magic. Maths with a proper label.”')+'</div>'+notice('<strong>Whisky z danych? Tak. Eliksir prawdy? Nie.</strong> Model streszcza wybrane relacje; nie zachowuje całej historii. Źródłowe obserwacje zostają dostępne. Braki nie znikają w rurce.','<strong>Data whisky? Yes. Truth serum? No.</strong> A model is a lossy description of selected relationships. Source observations remain available. Missing values do not vanish in the pipe.')+'<div class="fact"><b>1 338</b><span>'+t('par sąsiednich obserwacji','pairs of adjacent observations')+'</span></div><div class="fact"><b>4 → 3</b><span>'+t('modele w próbce → zakończone obliczenia; to nie certyfikat jakości danych','models in the sample → completed fits; not a data-quality certificate')+'</span></div><p class="subtle">'+t('Kliknij zawory. Dla różnic i skali śledzimy tę samą parę 447 → 448 i cursor: pin S wait on X.','Click the valves. Changes and scaling follow the same pair, 447 → 448, and cursor: pin S wait on X.')+'</p></aside></div>'+next(t('Co wyszło z tej destylacji?','What came out of the distillery?'));}
function calcContent(){const i=D.focus,j=1,dx=P.dx[i][j],dy=P.dy[i],z=P.z[i][j];switch(state.stage){
 case 0:return '<p class="eyebrow">'+t('01 / Najpierw etykieta wejścia','01 / Label the input first')+'</p><h2>'+t('Zero ≠ „nic się nie działo”.','Zero ≠ “nothing happened”.')+'</h2>'+warning()+'<p>'+t('W pozostałych kolumnach liczby braków to 0, 1 i 0. Maska wierszy oraz długości okien nie zachowały się. Nie oznaczamy żadnego konkretnego zera jako brakującego. Wyniki poniżej są rekonstrukcją edukacyjną obarczoną tym ograniczeniem.','Missing counts in the other columns are 0, 1 and 0. Row masks and window durations were not retained. We do not label any particular zero as missing. The following results are an educational reconstruction with this limitation.')+'</p><details><summary>'+t('Dlaczego braki mogą stworzyć fałszywy skok?','How can missing data create a false spike?')+'</summary><p>'+t('Ogólny przykład algebraiczny, nie oznaczenie wiersza tego zbioru: jeśli brakujące xₜ zastąpisz zerem, różnice na krawędziach luki stają się 0 − xₜ₋₁ oraz xₜ₊₁ − 0. Bez maski nie odróżnimy tego od prawdziwego spadku i wzrostu. Model sam tego nie naprawi.','General algebra, not an identified row in this dataset: replacing missing xₜ with zero creates boundary differences 0 − xₜ₋₁ and xₜ₊₁ − 0. Without a mask we cannot distinguish this from a real fall and rise. A model cannot repair it on its own.')+'</p></details>';
 case 1:return '<p class="eyebrow">'+t('02 / Co się zmieniło?','02 / What changed?')+'</p><h2>447 → 448 · cursor: pin S wait on X</h2><div class="equation">'+n(D.x[i+1][j])+' − '+n(D.x[i][j])+' = '+n(dx)+' s</div><p>'+t('Odejmujemy poprzednie okno od następnego. Pytamy o zmianę poziomu oczekiwania — nie o największą sumę w całym raporcie. To suma sekund oczekiwania, nie czas zegarowy okna.','Subtract the previous window from the next. We ask about the change in waiting, not the biggest total in the report. These are summed wait seconds, not the window’s wall-clock duration.')+'</p><div class="equation">Δ AAS = '+n(D.y[i+1])+' − '+n(D.y[i])+' = '+n(dy)+'</div><p>'+t('Cel zmienił się o tyle aktywnych sesji średnio. AAS i sekundy oczekiwania mają inne jednostki; nie dodajemy tych osi.','That is the change in average active sessions. AAS and wait seconds have different units; we do not add these axes.')+'</p>';
 case 2:return '<p class="eyebrow">'+t('03 / Wspólny język wielkości','03 / A common language of scale')+'</p><h2>'+t('Najpierw wyjaśnienie. Potem litera z.','Meaning first. The letter z second.')+'</h2><p>'+t('Od zmiany odejmujemy średnią zmian. Wynik dzielimy przez odchylenie standardowe zmian: typową skalę ich rozrzutu. To przygotowanie modelu, nie samo rozciągnięcie wykresu.','Subtract the mean change, then divide by the sample standard deviation: a scale of spread. This prepares the model; it is not merely stretching a chart.')+'</p><div class="equation">z = ('+n(dx)+' − '+n(P.mean[j],5)+') / '+n(P.sd[j],5)+' = '+n(z,5)+'</div><div class="calc-grid"><div class="calc-cell"><span>'+t('średnia Δx','mean Δx')+'</span><b>'+n(P.mean[j],5)+' s</b></div><div class="calc-cell"><span>'+t('odchylenie próby','sample deviation')+'</span><b>'+n(P.sd[j],2)+' s</b></div><div class="calc-cell"><span>'+t('wynik bez jednostki','unitless result')+'</span><b>'+n(z,5)+'</b></div></div><p>'+t('Średnia i skala pochodzą z 1 338 różnic. W wariancji próbki dzielimy sumę kwadratów odchyleń przez N−1 = 1 337.','Mean and scale come from 1,338 differences. Sample variance divides the sum of squared deviations by N−1 = 1,337.')+'</p>'+notice('z ≈ 12,57 oznacza zmianę ponad dwanaście takich skal od średniej. To duży skok wejścia, nie „12 razy więcej AAS”. Huber ogranicza reakcję na duży błąd przewidywania, ale nie daje pełnej ochrony przed skrajną wartością samej cechy.','z ≈ 12.57 means a change more than twelve such scales from the mean. It is a large input jump, not “12 times more AAS”. Huber limits the response to large prediction errors, but does not fully protect against extreme predictor values.');
 case 3:return modelCards();
 case 4:return '<p class="eyebrow">'+t('05 / Bramka zbieżności','05 / Convergence gate')+'</p><h2>'+t('Nie zbiegł? Nie głosuje.','Didn’t converge? No vote.')+'</h2><div class="model-grid">'+Object.keys(labels).map(m=>'<div class="model-tile '+(!D.fitStatus[m].converged?'blocked':'')+'"><h3>'+labels[m]+'</h3><span class="tag">'+(D.fitStatus[m].converged?t('ZBIEŻNY','CONVERGED'):'STOP')+'</span><p>'+(D.fitStatus[m].iterations?count(D.fitStatus[m].iterations,{one:'iteracja',few:'iteracje',many:'iteracji',other:'iteracji'},'iteration'):t('rozwiązany układ','solved system'))+'</p></div>').join('')+'</div><blockquote class="gate-quote">'+t('„Q95: jeszcze jedna iteracja i mam odpowiedź! Barman: stary, my już krzesła na stoły stawiamy.”','“Q95: one more iteration and I’ve got it! Bartender: mate, the chairs are already on the tables.”')+'</blockquote><p>'+t('Po 20 000 iteracji Q95 nie spełnił swoich kryteriów zakończenia. Możemy obejrzeć liczby z chwili zatrzymania, ale nie dopuszczamy ich do wspólnej kwalifikacji. Nie jest to dowód, że dane są złe. Zbieżność pozostałych modeli oznacza zakończenie obliczeń według kryterium — nie potwierdzenie jakości danych ani przyczynowości.','After 20,000 iterations Q95 had not met its stopping criteria. We can inspect its last numbers, but they cannot enter the combined classification. This does not prove the data are bad. Convergence of the other fits means they met their numerical criteria, not that data quality or causality has been established.')+'</p>';
 default:return '<p class="eyebrow">'+t('06 / Etykieta jest częścią wyniku','06 / The label is part of the result')+'</p><h2>'+t('Destylat z odnośnikiem do beczki.','A distillate with a route back to the barrel.')+'</h2><div class="package-comparison"><div><b>'+n(rawBytes/1000,1)+' kB</b><span class="subtle">'+t('macierz liczb w JSON','numerical matrix in JSON')+'</span></div><span class="arrow">→</span><div><b>'+n(by(JSON.stringify(packet()))/1000,1)+' kB</b><span class="subtle">'+t('pakiet dowodów w JSON','evidence packet in JSON')+'</span></div></div><p>'+t('To zmierzone bajty dwóch konkretnych reprezentacji. Nie współczynnik kompresji całego AWR, nie pomiar tokenów, nie obietnica oszczędności. Podsumowanie jest stratne: nie odtworzysz z niego pomiarów. Wrócisz po nie do zachowanego źródła.','These are measured bytes of two specific representations. Not a full-AWR compression ratio, a token count, or promised savings. The summary is lossy: it cannot reconstruct the measurements. Retrieve them from the retained source.')+'</p><p>'+t('Pakiet zawiera zakres, transformacje, współczynniki, braki, zbieżność, punkt wejścia i następne żądanie dowodu. Wątpliwości jadą razem z liczbami.','The packet carries scope, transformations, coefficients, missingness, convergence, an entry point and the next evidence request. Doubts travel with the numbers.')+'</p>';
}}
function bindDistil(){
 $('calc-content').onclick=e=>{const b=e.target.closest('[data-explain-model]');if(b&&$('calc-content').contains(b))showModelExplanation(b.dataset.explainModel);};
 const svg=$('apparatus');svg.querySelector('text:last-child').textContent=t('CZTERY MODELE. RÓŻNE PYTANIA. ŻADNYCH WYROKÓW.','FOUR MODELS. DIFFERENT QUESTIONS. NO VERDICTS.');
 const desktop=document.createElement('div');desktop.className='desktop-flow';svg.replaceWith(desktop);desktop.append(svg);const mobile=document.createElement('div');mobile.className='mobile-flow';mobile.innerHTML=mobileApparatus();desktop.after(mobile);
 document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{state.stage=+b.dataset.stage;document.querySelectorAll('[data-stage]').forEach(x=>x.setAttribute('aria-pressed',String(+x.dataset.stage===state.stage)));$('calc-content').innerHTML=calcContent();});
 $('play-flow').onclick=()=>{clearTimeout(flowTimer);const diagrams=document.querySelectorAll('.distill-svg');$('flow-status').textContent=state.reduce?t('Pomiary → różnice → skala → modele → kontrola. Ruch ograniczony: pokazujemy nieruchomy schemat.','Readings → changes → scale → models → checks. Reduced motion: showing a static diagram.'):t('Śledź drogę liczb. Objaśnienia kroków otwierasz zaworami poniżej.','Follow the numbers. Open each explanation with the valves below.');diagrams.forEach(s=>{s.classList.remove('running');void s.getBoundingClientRect();s.classList.add('running');});$('announcement').textContent=t('Pomiary pozostają lokalne. Cztery dopasowania; Q95 zatrzymany w bramce.','Measurements stay local. Four fits; Q95 stopped at the gate.');flowTimer=setTimeout(()=>diagrams.forEach(s=>s.classList.remove('running')),6200);};
}
function mobileApparatus(){return '<svg class="distill-svg" viewBox="0 0 320 360" role="img" aria-label="'+t('Lokalne pomiary, obliczenia i cztery modele. Q95 niedopuszczony.','Local measurements, calculations and four models. Q95 excluded.')+'"><path class="pipe" d="M160 74 V230 H47 M160 230 H269 M47 230 V255 M121 230 V255 M195 230 V255 M269 230 V255"/><path class="flow" d="M160 74 V230 H47 M160 230 H269 M47 230 V255 M121 230 V255 M195 230 V255 M269 230 V255"/><rect class="metal" x="45" y="12" width="230" height="63" rx="12"/><text class="label" x="160" y="38" text-anchor="middle">1 339 × 5</text><text x="160" y="59" text-anchor="middle">'+t('POMIARY ZOSTAJĄ LOKALNIE','MEASUREMENTS STAY LOCAL')+'</text><path class="copper" d="M125 123 H195 L210 165 Q212 198 160 202 Q108 198 110 165Z"/><text class="label" x="160" y="153" text-anchor="middle">Δ → z → β</text><text x="160" y="177" text-anchor="middle">'+t('OBLICZENIA','CALCULATIONS')+'</text>'+['Ridge','EN','Huber','Q95'].map((s,i)=>{const x=27+i*74;return '<path class="bottle '+(i===3?'rejected':'')+'" d="M'+(x+9)+' 250 H'+(x+31)+' V263 L'+(x+39)+' 277 V323 H'+(x+1)+' V277 L'+(x+9)+' 263Z"/><text x="'+(x+20)+'" y="297" text-anchor="middle" class="'+(i===3?'danger-label':'label')+'">'+s+'</text><text x="'+(x+20)+'" y="346" text-anchor="middle" class="'+(i===3?'danger-label':'')+'">'+(i===3?'STOP':'✓')+'</text>';}).join('')+'</svg>';}
function modelCards(){
 return '<p class="eyebrow">'+t('04 / Cztery sposoby zadawania pytań','04 / Four ways to ask questions')+'</p><p>'+t('Kliknij model. Wyjaśnimy go przy piwie — bez zakładania, że znasz wzory.','Click a model. We’ll explain it over a beer — no formulas assumed.')+'</p><div class="model-grid">'+Object.keys(labels).map(key=>{const c=window.ModelExplanations.get(key,state.lang,D,P);return '<button type="button" class="model-tile model-explain" data-explain-model="'+key+'" aria-haspopup="dialog" aria-controls="model-dialog"><span class="model-name">'+esc(c.name)+'</span><span class="model-teaser">'+esc(c.teaser)+'</span><span class="model-invite"><span aria-hidden="true">🍺</span> '+esc(c.explain)+' <span aria-hidden="true">↗</span></span></button>';}).join('')+'</div><p>'+t('Ridge liczymy teraz w przeglądarce. Wyniki trzech pozostałych modeli zachowano z wcześniejszych obliczeń tych samych danych. Każdy patrzy na problem inaczej. „Przewidywanie” oznacza tu oszacowanie zmiany AAS z równoczesnych zmian oczekiwań, nie prognozę przyszłości. Badamy ten sam zbiór, na którym dopasowano modele; nie jest to test trafności na nowych danych.','Ridge runs in the browser now. The other three results were retained from earlier calculations on these same data. Each takes a different view. “Prediction” here means estimating AAS change from simultaneous wait changes, not forecasting the future. We inspect the same data used for fitting; this is not an accuracy test on unseen data.')+'</p>';
}
function showModelExplanation(key){
 const c=window.ModelExplanations.get(key,state.lang,D,P);
 $('beer-model').textContent=c.name+' / '+t('po ludzku','in plain words');$('beer-title').textContent=c.title;
 $('close-model').setAttribute('aria-label',t('Zamknij wyjaśnienie','Close explanation'));
 $('beer-body').innerHTML='<p class="beer-kicker">'+esc(c.eyebrow)+'</p><blockquote class="beer-quote">'+esc(c.hook)+'</blockquote>'+c.paragraphs.map(s=>'<p>'+esc(s)+'</p>').join('')+'<section class="beer-example"><h3>'+esc(c.exampleTitle)+'</h3>'+(c.equation?'<p class="beer-equation">'+esc(c.equation)+'</p>':'')+'<p>'+esc(c.example)+'</p></section><div class="beer-takeaway"><span>'+esc(c.rememberLabel)+'</span><strong>'+esc(c.remember)+'</strong></div><details class="beer-maths"><summary>'+esc(c.mathLabel)+'</summary>'+c.math.map(s=>'<p>'+esc(s)+'</p>').join('')+window.LearningPanels.lab(key,state.lang,D,P)+'</details><p class="beer-limit"><strong>'+esc(c.limitLabel)+': </strong>'+esc(c.limit)+'</p><button type="button" id="beer-done">'+esc(c.close)+'</button>';
 window.LearningPanels.bindLab(key,state.lang,D);
 $('beer-done').onclick=()=>$('model-dialog').close();$('close-model').onclick=()=>$('model-dialog').close();
 $('model-dialog').dataset.model=key;$('model-dialog').showModal();$('beer-body').scrollTop=0;
}
function signal(){return intro(3,t('Największy słupek<br><em>nie wybiera pytania.</em>','The tallest bar<br><em>doesn’t choose the question.</em>'),t('Najpierw porównaj dwa pytania do danych: P90 i P99. Potem wybierz model, zmień ustawienia albo otwórz rachunek. Wysokość słupka to wskazówka do dalszego badania, nie werdykt.','First compare two questions asked of the data: P90 and P99. Then choose a model, change settings or open the arithmetic. A bar’s height is a lead for investigation, not a verdict.'))+
 '<div class="layout"><section class="panel"><div class="panel-head"><p class="eyebrow">'+t('WYNIK MODELU · NIE CZAS DO ODZYSKANIA','MODEL SCORE · NOT RECOVERABLE TIME')+'</p><span class="pill">'+t('Δ AAS / 4 cechy','Δ AAS / 4 features')+'</span></div><div class="panel-content"><div class="model-controls"><label>'+t('Model','Model')+'<select id="model-select">'+Object.entries(labels).map(([key,label])=>'<option value="'+key+'" '+(state.model===key?'selected':'')+'>'+label+'</option>').join('')+'</select></label><label>'+t('Wielkość zmian cechy','Predictor-change magnitude')+'<select id="metric-select">'+['p90','p99','max'].map(key=>'<option value="'+key+'" '+(state.metric===key?'selected':'')+'>'+key.toUpperCase()+'</option>').join('')+'</select></label></div><div id="rank-content"></div><div id="lambda-field" class="field"><label for="lambda">'+t('Kara Ridge λ — przeliczenie lokalne','Ridge penalty λ — local recomputation')+'<output id="lambda-value">'+n(state.lambda,3)+'</output></label><input id="lambda" type="range" min="-3" max="1" step=".05" value="'+Math.log10(state.lambda)+'"></div><button id="reset-fit" class="text-button">'+t('↶ Wróć do Ridge λ = 0,05, P99','↶ Reset to Ridge λ = 0.05, P99')+'</button><details id="ridge-details"><summary>'+t('Pokaż równania i eliminację Gaussa','Show equations and Gaussian elimination')+'</summary><div id="gauss-detail"></div></details></div></section><aside class="side-note"><div class="dialogue"><span class="speaker">DEV</span>'+t('„Czyli mniejszy wykres może być lepszym tropem?”','“So a smaller chart can be a better lead?”')+'</div><div class="dialogue"><span class="speaker">DBA</span>'+t('„Zależy, o co pytasz. Zmień P99 na P90.”','“Depends on the question. Switch P99 to P90.”')+'</div>'+notice('<strong>Nie ma jednego magicznego rankingu.</strong> P90 pokazuje inną skalę zmian niż P99 czy maksimum. JAS-MIN zestawia osobno wyliczone listy TOP z dopuszczonych modeli. Tutaj oglądasz pojedynczą listę, aby zrozumieć jej rachunek.','<strong>No single magic ranking.</strong> P90 uses a different change magnitude from P99 or the maximum. JAS-MIN combines separately computed TOP lists from eligible fits. Here you inspect one list to understand its arithmetic.')+warning()+'</aside></div>'+next(t('Daj AI lepszy punkt zaczepienia','Give AI a better starting point'));}
function updateSignal(){
 $('prediction-payoff').innerHTML=S.prediction(state.lang,D,P,fit,state.guess);
 const selected=state.model==='ridge'?fit:D.models[state.model],rows=M.ranking(D,P,selected,state.metric),eligible=D.fitStatus[state.model].converged,top=rows[0],max=Math.max(...rows.map(r=>r.impact))||1;
 const bars=rows.map((r,i)=>'<div class="rank-row"><span class="rank-index">0'+(i+1)+'</span><span class="rank-name">'+esc(r.name)+(r.missing?'<small class="warning-symbol">'+count(r.missing,{one:'brak',few:'braki',many:'braków',other:'braku'},'missing entry').replace('entrys','entries')+t(' → wypełnienie zerem',' → zero-filled')+'</small>':'')+'</span><div class="bar-track"><div class="bar" style="--width:'+(r.impact/max*100)+'%;--color:'+colors[r.j]+'"></div></div><span class="rank-value">'+n(r.impact,2)+'</span></div>').join('');
 $('rank-content').innerHTML=(!eligible?notice('<strong>Q95: wynik niedopuszczony do kwalifikacji.</strong> Poniższe liczby pokazują stan niedokończonego rozwiązania, nie ważny głos modelu.','<strong>Q95: excluded from classification.</strong> The numbers below show an unfinished solution, not a valid model vote.','danger'):'')+'<div class="'+(!eligible?'visually-blocked':'')+'">'+bars+'</div><p class="micro">'+t('jednostka wyniku: AAS · tylko dodatnie współczynniki tworzą dodatni wynik','score unit: AAS · only positive coefficients yield a positive score')+'</p>'+window.LearningPanels.provenance(state.lang,D,P,selected,state.model,state.metric,top);
 const guideWasOpen=$('percentile-details')?.open;let guide=$('metric-guide');if(!guide){guide=document.createElement('div');guide.id='metric-guide';$('rank-content').before(guide);}guide.innerHTML=window.LearningPanels.metricGuide(state.lang,state.metric);if(guideWasOpen)$('percentile-details').open=true;
 $('lambda-field').hidden=state.model!=='ridge';$('ridge-details').hidden=state.model!=='ridge';$('lambda-value').textContent=n(state.lambda,4);$('gauss-detail').innerHTML=gaussDetail();
 const slider=$('gauss-step');if(slider)slider.oninput=()=>updateGauss(+slider.value);
 const showSystem=$('show-beta-system');if(showSystem)showSystem.onclick=()=>{$('ridge-details').open=true;$('ridge-details').scrollIntoView({behavior:state.reduce?'instant':'smooth',block:'start'});$('ridge-details').querySelector('summary').focus({preventScroll:true});};
}
function gaussDetail(){return S.gaussIntro(state.lang,D,P,fit)+'<div class="field"><label for="gauss-step">'+t('Kroki: 6 eliminacji + 4 podstawienia','Steps: 6 eliminations + 4 back substitutions')+'</label><input id="gauss-step" type="range" min="0" max="'+(fit.steps.length+fit.beta.length)+'" step="1" value="0"></div><div id="gauss-state" aria-live="polite">'+gaussState(0)+'</div>';}
function gaussState(k){
 const step=k>0&&k<=fit.steps.length?fit.steps[k-1]:null;
 const a=k===0?fit.A.map((r,i)=>[...r,fit.rhs[i]]):step?step.matrix:fit.steps.at(-1).matrix;
 return S.gaussStep(state.lang,fit,k)+'<div class="table-wrap"><table class="data-table"><caption>'+t('Macierz po bieżącym kroku; liczby zaokrąglone','Matrix after the current step; rounded values')+'</caption><thead><tr>'+['β1','β2','β3','β4',t('prawa strona','right side')].map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+a.map((r,i)=>'<tr class="'+(step&&i===step.target?'gauss-active':'')+'">'+r.map(v=>'<td>'+n(Math.abs(v)<.000005?0:v,5)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
}
function updateGauss(k){$('gauss-state').innerHTML=gaussState(k);}
function bindSignal(){updateSignal();$('model-select').onchange=e=>{state.model=e.target.value;updateSignal();};$('metric-select').onchange=e=>{state.metric=e.target.value;updateSignal();};$('lambda').oninput=e=>{state.lambda=M.lambdaFromSlider(+e.target.value);fit=M.ridge(P,state.lambda);updateSignal();};$('reset-fit').onclick=()=>{state.lambda=.05;state.model='ridge';state.metric='p99';fit=M.ridge(P,.05);render();};}
function investigate(){const h=handoff(),lead=h.lead,maxResmgr=M.ranking(D,P,fit,'max').find(r=>r.j===3),p99Resmgr=M.ranking(D,P,fit,'p99').find(r=>r.j===3);return intro(4,t('Nie „AI, napraw bazę”.<br><em>AI, sprawdź ten trop.</em>','Not “AI, fix the database”.<br><em>AI, investigate this lead.</em>'),t('Model zawęża pytanie. LLM układa plan. MCP pozwala sięgnąć po konkretny dowód. Potem sprawdzamy, czy hipoteza nadal się broni.','The model narrows the question. The LLM builds a plan. MCP provides access to specific evidence. Then we check whether the hypothesis still holds.'))+
 '<div class="callout handoff-context">'+t('Do dalszego badania i pakietu wybieramy obecny Ridge × P99 (λ = ','For the handoff and packet we use the current Ridge × P99 (λ = ')+n(h.lambda,4)+t('). Inne modele i miary pozostają porównaniami. Q95 nadal nie jest dopuszczony.','). Other models and metrics remain comparisons. Q95 is still excluded.')+'</div><div class="evidence-route"><div class="route-node"><strong>01 / '+t('FAKT O MODELU','FACT ABOUT THE MODEL')+'</strong><h3>'+esc(lead?.name||t('Najpierw sprawdź wejście','Check the input first'))+'</h3><p>Ridge λ = '+n(h.lambda,4)+' · P99 · '+n(lead?.impact||0,3)+' AAS. '+t('To ten sam wynik, który zapisujemy w pakiecie. Jest tropem do sprawdzenia, nie wskazaniem blokującej sesji.','The packet contains this same result. It is an investigative lead, not an identified blocking session.')+'</p></div><span class="route-arrow" aria-hidden="true">→</span><div class="route-node"><strong>02 / '+t('HIPOTEZA','HYPOTHESIS')+'</strong><h3>'+t('Sprawdź współwystępujące SQL','Inspect associated SQL')+'</h3><p>'+t('Które SQL współwystępują z tym oczekiwaniem? Jakie mamy pokrycie ASH? Co mogłoby podważyć związek?','Which SQL statements are associated with this wait? What ASH coverage is available? What could weaken the proposed relationship?')+'</p></div><span class="route-arrow" aria-hidden="true">→</span><div class="route-node"><strong>03 / '+t('BRAKUJĄCY DOWÓD','MISSING EVIDENCE')+'</strong><h3>'+t('Zapytaj, nie dopowiadaj','Ask, don’t invent')+'</h3><p>'+t('Ta próbka nie zawiera przypisania SQL ani relacji blocker/waiter. Nie wolno ich wymyślić na podstawie samego współczynnika.','This sample has neither SQL attribution nor blocker/waiter evidence. A coefficient cannot supply either.')+'</p></div></div><div class="layout"><section class="panel"><div class="panel-head"><p class="eyebrow">'+t('TWÓJ RUCH / WYBIERZ KOLEJNE PYTANIE','YOUR MOVE / CHOOSE THE NEXT QUESTION')+'</p><span class="pill">'+t('scenka LLM · bez połączenia','scripted LLM scene · offline')+'</span></div><div class="panel-content"><h2>'+t('Co zlecasz pomocnikowi?','What do you ask the assistant to do?')+'</h2><button class="choice" data-decision="tune">'+t('„Największy współczynnik? Zmień parametry bazy.”','“Biggest coefficient? Change database parameters.”')+'</button><button class="choice" data-decision="all">'+t('„Dociągnij cały AWR. Może coś znajdziesz.”','“Fetch the entire AWR. Maybe you’ll find something.”')+'</button><button class="choice" data-decision="evidence">'+t('„Sprawdź SQL powiązane z tym tropem i jakość przypisania.”','“Inspect SQL associated with this lead and attribution quality.”')+'</button><div id="decision-feedback" class="result-box" aria-live="polite">'+decisionNote()+'</div><details><summary>'+t('Dlaczego nie wystarczy sama zgoda trzech modeli?','Why isn’t agreement between three models enough?')+'</summary><p>'+t('Wszystkie widzą ten sam wycinek i odziedziczone braki. Wspólna wada wejścia może prowadzić do zgodnych, lecz mylących wyników. Potrzebujemy niezależnej weryfikacji, kontekstu obciążenia i danych o czasie okien.','All see the same subset and inherited missingness. A shared input defect can produce agreement and still mislead. We need independent verification, workload context and window-duration information.')+'</p></details></div></section><aside><div class="receipt"><p class="eyebrow">ONE MORE QUERY / TO GO</p><h2>'+t('Twój destylat<br>ma etykietę.','Your distillate<br>has a label.')+'</h2><hr><p>'+t('1 339 pomiarów<br>4 cechy · 1 338 różnic<br>Ridge na żywo<br>Q95: niedopuszczony<br>Braki: jawnie opisane','1,339 observations<br>4 features · 1,338 changes<br>Live local Ridge<br>Q95: excluded<br>Missingness: disclosed')+'</p><p class="receipt-settings">Ridge × P99 · λ = '+n(h.lambda,4)+'</p><hr><p>'+t('Pakiet nie zawiera całej historii. Źródła zostają lokalnie. LLM dostaje trop i ograniczenia.','The packet is not the whole story. Sources stay local. The LLM gets a lead and its limits.')+'</p><details class="packet-preview"><summary>'+t('Podejrzyj dokładnie ten pakiet','Preview this exact packet')+'</summary><pre id="packet-preview" class="tool-code">'+esc(JSON.stringify(packet(),null,2))+'</pre></details><button id="download-packet">'+t('↓ Pobierz pakiet dowodów','↓ Download evidence packet')+'</button><p class="micro" style="margin-top:12px">'+count(by(JSON.stringify(packet())),{one:'bajt',few:'bajty',many:'bajtów',other:'bajtu'},'byte')+t(' JSON · nic nie wysłano',' JSON · nothing uploaded')+'</p></div></aside></div><section class="panel" style="margin-top:30px"><div class="panel-content"><p class="eyebrow">'+t('JESZCZE JEDNO PYTANIE, ZANIM ZAMÓWISZ','ONE LAST QUESTION BEFORE YOU ORDER')+'</p><h2>'+t('resmgr: przy MAX wynik jest większy. Czy już zamawiamy tuning?','resmgr: the MAX score is larger. Shall we order some tuning?')+'</h2><p>'+t('W obecnym Ridge: P99 = ','In the current Ridge fit: P99 = ')+n(p99Resmgr.impact)+' AAS; MAX = '+n(maxResmgr.impact)+t(' AAS. Ten sam model, większa wielkość zmiany. Ale 963 wpisy tej cechy uzupełniono zerami i nie wiemy które. Co sprawdzasz najpierw?',' AAS. Same model, a larger change magnitude. But 963 entries for this feature were zero-filled and we do not know which. What do you check first?')+'</p><p class="micro">'+t('Miejsce resmgr przy MAX: ','resmgr rank at MAX: ')+['ridge','elastic','huber'].map(key=>labels[key]+' '+(M.ranking(D,P,key==='ridge'?fit:D.models[key],'max').findIndex(r=>r.j===3)+1)+'/4').join(' · ')+'</p><h2 class="sr-only">'+t('Wybierz odpowiedź','Choose an answer')+'</h2><div class="switches"><button data-quiz="believe">'+t('Wierzę zgodnym modelom','Trust the agreeing models')+'</button><button data-quiz="drop">'+t('Uznaję wszystkie zera za braki','Treat all zeros as missing')+'</button><button data-quiz="verify">'+t('Sprawdzam źródło i maskę braków','Check the source and missingness mask')+'</button></div><div id="quiz-feedback" class="feedback" aria-live="polite">'+quizNote()+'</div></div></section><div class="recap"><div><b>01. '+t('Zobacz','See')+'</b><p>'+t('Skala obrazu nie jest skalą ważności.','Visual scale is not importance.')+'</p></div><div><b>02. '+t('Policz','Calculate')+'</b><p>'+t('Model daje kontrolowany skrót, nie wyrok.','A model gives a controlled summary, not a verdict.')+'</p></div><div><b>03. '+t('Sprawdź','Verify')+'</b><p>'+t('Dobre pytanie otwiera właściwe źródło dowodów.','A good question opens the right evidence source.')+'</p></div></div><div class="closing-line"><p class="eyebrow">DBA + DEV</p><h2>'+t('„Dobra. Zanim następna kolejka — jeszcze jedno zapytanie.”','“Right. Before the next round — one more query.”')+'</h2><p>Stop being DBA. Stop being DEV. Performance tuning is math!</p><p class="subtle">'+t('Role nie znikają. Łączymy wiedzę o bazie, kodzie i liczbach, żeby zadać lepsze pytanie.','The roles do not disappear. We combine database knowledge, code and numbers to ask a better question.')+'</p></div><div class="cta"><button class="text-button" data-back>'+t('← Wróć do modeli','← Back to the models')+'</button><button id="restart" class="primary">'+t('Jeszcze jeden SELECT? ↻','One more query? ↻')+'</button></div>';}
function decisionNote(){const h=handoff();if(!state.decision)return '';if(state.decision==='tune')return notice('<strong>To byłby skok ponad dowodami.</strong> Regresja nie wskazała bezpiecznej zmiany parametrów. Nie wykazała też przyczyny ani odzyskiwalnego czasu. Najpierw potrzebujemy weryfikacji.','<strong>That would outrun the evidence.</strong> Regression did not identify a safe parameter change, establish cause or prove recoverable time. Verification comes first.','warning');if(state.decision==='all')return notice('Więcej źródeł może pomóc, ale to nadal nieprecyzyjne zadanie. Mamy konkretną lukę: powiązane SQL i jakość przypisania. Zacznijmy od niej.','More sources can help, but this is still an unfocused task. We have a specific gap: associated SQL and attribution quality. Start there.','warning');return notice('<strong>To jest sprawdzalny następny krok.</strong> Wynik żądania może wzmocnić hipotezę, osłabić ją albo ujawnić brak wystarczających danych.','<strong>That is a verifiable next step.</strong> The response could strengthen the hypothesis, weaken it, or reveal insufficient data.')+'<pre class="tool-code">'+esc(JSON.stringify(h.request?{tool:h.request.tool,arguments:h.request.arguments}:{status:'No positive Ridge lead; inspect data quality first'},null,2))+'</pre><p class="tag">'+t('PLANOWANE ŻĄDANIE · NIE WYKONANO','PROPOSED REQUEST · NOT EXECUTED')+'</p><p class="subtle">'+t('To szablon dla funkcji serwera JAS-MIN. Najpierw wybiera się projekt i uruchamia start_performance_analysis; otrzymany analysis_id oraz wybrany project_id zastępują znaczniki w nawiasach. Nie znamy tu tych identyfikatorów i nie łączymy się z MCP. SQL_ID, planów i blockerów nie pokazujemy, bo nie mamy tu tych dowodów. Korelacja SQL z oczekiwaniem także nie jest dowodem blocker/waiter.','This is a template for a JAS-MIN server function. Select a project and call start_performance_analysis first; replace the angle-bracket placeholders with its analysis_id and the selected project_id. This sample has neither identifier and does not connect to MCP. It shows no SQL IDs, plans or blockers because that evidence is not present. SQL/wait correlation would still not prove a blocker/waiter relationship.')+'</p>';}
function quizNote(){if(!state.quiz)return '';return state.quiz==='verify'?notice('<strong>Właśnie o to chodzi.</strong> Najpierw ustal, które zera są pomiarem, a które wypełnieniem. Dopiero potem porównuj sensownie przygotowane warianty modelu. Największy skok może być rzeczywistym zdarzeniem albo efektem krawędzi luki wypełnionej zerem. Bez maski nie rozstrzygniemy tego.','<strong>Exactly.</strong> Establish which zeros are measured and which are placeholders. Then compare properly prepared fits. The largest jump could be real or could be an edge of a zero-filled gap. Without the mask we cannot settle that.'):state.quiz==='drop'?notice('Nie znamy położenia braków. Część zer może być prawdziwym pomiarem. Uznanie wszystkich zer za braki byłoby kolejnym nieudowodnionym założeniem.','We do not know where the missing entries are. Some zeros may be genuine measurements. Treating every zero as missing would introduce another unsupported assumption.','warning'):notice('Zgodne modele mogą odziedziczyć ten sam błąd wejścia. Zbieżność obliczeń i zgodność rankingu nie zastępują kontroli jakości danych.','Agreeing models can inherit the same input defect. Numerical convergence and ranking agreement cannot replace data-quality checks.','warning');}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function bindInvestigate(){document.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>{state.decision=b.dataset.decision;$('decision-feedback').innerHTML=decisionNote();});document.querySelectorAll('[data-quiz]').forEach(b=>b.onclick=()=>{state.quiz=b.dataset.quiz;$('quiz-feedback').innerHTML=quizNote();});$('download-packet').onclick=()=>download('one-more-query-evidence.json',JSON.stringify(packet()),'application/json');$('restart').onclick=()=>navigate(0);}
function about(){
 $('about-title').textContent=t('Co jest prawdziwe?','What is real?');$('close-dialog').setAttribute('aria-label',t('Zamknij','Close'));
 $('about-body').innerHTML='<p>'+t('Ta próbka używa 1 339 zachowanych pomiarów Oracle. Wartości i nazwy czterech zdarzeń pozostały niezmienione. Nie zawiera nazw organizacji, hostów, baz ani dat. Historia pubowa i dialogi są fikcją dydaktyczną.','This sample uses 1,339 retained Oracle observations. Values and four event names are unchanged. It contains no organization, host, database names or dates. The pub story and dialogue are educational fiction.')+'</p><ul><li>'+t('Cel: historyczny, zaokrąglony Load Profile / AAS. Predyktory: sumy sekund oczekiwania w oknach, nie tempo oczekiwania. Nie znamy długości okien; nie normalizujemy ich pozornie do AAS.','Target: historical rounded Load Profile / AAS. Predictors: total wait seconds per window, not wait rates. Window durations are unknown; we do not pretend to normalize those totals to AAS.')+'</li><li>'+t('Braki uzupełnione zerami: 0, 1, 0, 963. Nie zachowała się maska wierszy. Wszystkie dopasowania czterocechowe dziedziczą tę niepewność.','Zero-filled missing entries: 0, 1, 0, 963. The row mask was not retained. All four-feature fits inherit that uncertainty.')+'</li><li>'+t('Dopasowanie: 1 338 kolejnych różnic, centrowanie celu, standaryzacja cech z N−1. Ridge: średnia strata kwadratowa / 2 + kara L2 / 2. Przeglądarka liczy i rozwiązuje rzeczywisty układ czterech równań.','Fitting: 1,338 adjacent differences, centered target, predictor standardization using N−1. Ridge: mean squared loss / 2 + L2 penalty / 2. The browser computes and solves the actual four-equation system.')+'</li><li>'+t('EN, Huber i Q95: zachowane ślady dopasowań, nie animowana transmisja z Oracle. Q95 niezbieżny po 20 000 iteracji — bez głosu w kwalifikacji.','EN, Huber and Q95: retained numerical fits, not a live feed from Oracle. Q95 failed to converge after 20,000 iterations and cannot vote in classification.')+'</li><li>'+t('Rankingi to β w jednostkach źródłowych × percentyl bezwzględnych zmian. To nie zidentyfikowany koszt przyczynowy ani obietnica odzyskania AAS/CPU.','Rankings multiply original-unit beta by a percentile of absolute changes. They are neither identified causal costs nor promised AAS/CPU recovery.')+'</li><li>'+t('Kalkulator kontekstu jest ilustracją z edytowalnymi założeniami, nie benchmarkiem, cennikiem ani informacją o limitach konkretnego modelu.','The context calculator is an illustration with editable assumptions, not a benchmark, price list or a specific model’s capacity.')+'</li><li>'+t('Żądanie MCP jest planowane i niewykonane. Żadne dane nie opuszczają przeglądarki. Publikacja tych anonimowych pomiarów została zatwierdzona przez autora. Kurs nie udostępnia źródłowych raportów ani nie wysyła danych do AI.','The MCP request is proposed, not executed. No data leaves the browser. The author approved publication of these anonymous measurements. The course exposes no source reports and uploads no data to AI.')+'</li></ul><div class="link-row"><button id="download-source">'+t('↓ Pobierz zachowaną macierz JSON','↓ Download the retained JSON matrix')+'</button></div><p class="micro" style="margin-top:15px">'+t('Wykresy pokazują wszystkie obserwacje, bez próbkowania. Maksima i wyniki są liczone z tych samych liczb.','Charts show every observation, with no downsampling. Maxima and scores are calculated from these same values.')+'</p>';
 $('download-source').onclick=()=>download('one-more-query-observations.json',JSON.stringify(M.sourceData(D)),'application/json');$('data-dialog').showModal();
}
function parseHash(){const m=location.hash.match(/^#(pl|en)\/([0-4])$/);if(m){state.lang=m[1];state.scene=+m[2];}}
parseHash();$('language').onclick=()=>{state.lang=state.lang==='pl'?'en':'pl';history.replaceState(null,'','#'+state.lang+'/'+state.scene);render();};$('motion').onclick=()=>{state.reduce=!state.reduce;document.body.classList.toggle('reduce-motion',state.reduce);$('motion').textContent=t('Ogranicz ruch','Reduce motion');$('motion').setAttribute('aria-pressed',String(state.reduce));if(state.reduce){cancelAnimationFrame(animation);clearTimeout(flowTimer);document.querySelectorAll('.distill-svg').forEach(s=>s.classList.remove('running'));if(state.scene===0)drawCharts();}};$('about').onclick=about;$('close-dialog').onclick=()=>$('data-dialog').close();window.addEventListener('hashchange',()=>{parseHash();render();});
// Read-only inspection hook for numerical and browser regression tests.
window.OneMoreQuery={getState:()=>({...state}),getFit:()=>({...fit,beta:fit.beta.slice()}),getEvidence:()=>packet(),prepared:P};
render();
})();
